package android.graphics.drawable; import android.graphics.*; import android.content.res.*; public class AnimatedVectorDrawable extends VectorDrawable implements Animatable2 { private boolean running; private Drawable vector; public void setVector(Drawable d){vector=d;if(d!=null)d.setBounds(getBounds());} public void draw(Canvas c){if(vector!=null)vector.draw(c);} protected void onBoundsChange(Rect r){if(vector!=null)vector.setBounds(r);} public int getIntrinsicWidth(){return vector==null?-1:vector.getIntrinsicWidth();} public int getIntrinsicHeight(){return vector==null?-1:vector.getIntrinsicHeight();} public void registerAnimationCallback(Animatable2.AnimationCallback c){} public boolean unregisterAnimationCallback(Animatable2.AnimationCallback c){return false;} public void clearAnimationCallbacks(){} public void start(){running=true;} public void stop(){running=false;} public boolean isRunning(){return running;} }